class CampaignProgress { int missionsCompleted=0,totalKills=0,alarm=0,requisition=0,investigationClues=0; String activeMissionId=''; final Map<String,int> factionKills={}; void beginMission(String id){activeMissionId=id;} void recordKill(String faction){totalKills++;factionKills[faction]=(factionKills[faction]??0)+1;} void completeMission({int reward=0}){missionsCompleted++;requisition+=reward;activeMissionId='';} Map<String,dynamic> toJson()=>{'missionsCompleted':missionsCompleted,'totalKills':totalKills,'alarm':alarm,'requisition':requisition,'investigationClues':investigationClues,'activeMissionId':activeMissionId,'factionKills':factionKills}; void loadJson(dynamic raw){if(raw is! Map)return;missionsCompleted=(raw['missionsCompleted'] as num?)?.toInt()??0;totalKills=(raw['totalKills'] as num?)?.toInt()??0;alarm=(raw['alarm'] as num?)?.toInt()??0;requisition=(raw['requisition'] as num?)?.toInt()??0;investigationClues=(raw['investigationClues'] as num?)?.toInt()??0;activeMissionId=raw['activeMissionId'] as String? ?? '';factionKills.clear();if(raw['factionKills'] is Map)(raw['factionKills'] as Map).forEach((k,v){if(k is String&&v is num)factionKills[k]=v.toInt();});} }
